pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(address(this)); // set initial owner via admin
        address initialOwner = c.owner();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        if (!success) vm.assume(false);
        assertTrue(c.owner() == newOwner || c.owner() == initialOwner);
    }
}

