import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin) public {
        vm.assume(nonAdmin != address(0) && nonAdmin != address(this));
        address ownerBefore = c.owner();
        vm.prank(nonAdmin);
        (bool reverted,) = address(c).call(abi.encodeWithSignature("setOwner(address)", address(1)));
        assertTrue(reverted && c.owner() == ownerBefore);
    }
}

